<!DOCTYPE html>
<html lang="pt">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Expediente arquivado | Gestão de Expedientes</title><link rel="stylesheet" href="assets/css/style.css"></head>
<body class="app-page"><header class="topbar"><a class="topbar-brand" href="dashboard.php"><span>GE</span> Gestão de Expedientes</a><a class="logout-button" href="arquivo.php">Voltar ao arquivo</a></header><main class="content-shell"><p class="section-kicker">Registo preservado</p><div class="page-heading"><div><h1><?= htmlspecialchars($expedition['reference_code'], ENT_QUOTES, 'UTF-8') ?></h1><p class="muted"><?= htmlspecialchars($expedition['subject'], ENT_QUOTES, 'UTF-8') ?></p></div><span class="state-badge state-archived">Arquivado</span></div><?php if ($message): ?><div class="flash <?= htmlspecialchars($message['type'], ENT_QUOTES, 'UTF-8') ?>" role="status"><?= htmlspecialchars($message['message'], ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><section class="detail-panel"><h2>Dados do expediente</h2><dl class="detail-data"><div><dt>Remetente/origem</dt><dd><?= htmlspecialchars($expedition['origin'], ENT_QUOTES, 'UTF-8') ?></dd></div><div><dt>Destinatário/setor</dt><dd><?= htmlspecialchars($expedition['destination'], ENT_QUOTES, 'UTF-8') ?></dd></div><div><dt>Data de entrada</dt><dd><?= htmlspecialchars(date('d/m/Y H:i', strtotime($expedition['received_at'])), ENT_QUOTES, 'UTF-8') ?></dd></div><div><dt>Registado por</dt><dd><?= htmlspecialchars($expedition['created_by_name'] ?? 'Utilizador removido', ENT_QUOTES, 'UTF-8') ?></dd></div></dl><div class="description-block"><dt>Descrição</dt><p><?= nl2br(htmlspecialchars($expedition['description'] ?: 'Sem descrição.', ENT_QUOTES, 'UTF-8')) ?></p></div></section><section class="archive-record"><p class="section-kicker">Informação do arquivamento</p><dl class="detail-data"><div><dt>Arquivado por</dt><dd><?= htmlspecialchars($archive['archived_by_name'] ?? 'Utilizador removido', ENT_QUOTES, 'UTF-8') ?></dd></div><div><dt>Data de arquivamento</dt><dd><?= htmlspecialchars(date('d/m/Y H:i', strtotime($archive['archived_at'])), ENT_QUOTES, 'UTF-8') ?></dd></div><div><dt>Referência</dt><dd><?= htmlspecialchars($archive['archive_reference'] ?: 'Sem referência', ENT_QUOTES, 'UTF-8') ?></dd></div></dl><?php if ($archive['notes']): ?><div class="description-block"><dt>Observação</dt><p><?= nl2br(htmlspecialchars($archive['notes'], ENT_QUOTES, 'UTF-8')) ?></p></div><?php endif; ?></section><?php if ($tramitacoes): ?><section class="timeline-panel archive-history"><h2>Histórico de tramitação</h2><ol class="timeline"><?php foreach ($tramitacoes as $item): ?><li><div class="timeline-marker"></div><div class="timeline-content"><div class="timeline-heading"><strong><?= htmlspecialchars($item['destination'], ENT_QUOTES, 'UTF-8') ?></strong><span><?= htmlspecialchars(date('d/m/Y H:i', strtotime($item['sent_at'])), ENT_QUOTES, 'UTF-8') ?></span></div><p><strong>Origem:</strong> <?= htmlspecialchars($item['sender_name'] ?? 'Utilizador removido', ENT_QUOTES, 'UTF-8') ?></p><p><strong>Responsável:</strong> <?= htmlspecialchars($item['responsible_name'] ?? 'Utilizador removido', ENT_QUOTES, 'UTF-8') ?></p><?php if ($item['observation']): ?><p><strong>Observação:</strong> <?= nl2br(htmlspecialchars($item['observation'], ENT_QUOTES, 'UTF-8')) ?></p><?php endif; ?></div></li><?php endforeach; ?></ol></section><?php endif; ?><?php if ($despachos): ?><section class="timeline-panel archive-history"><h2>Histórico de despachos</h2><ol class="timeline"><?php foreach ($despachos as $dispatch): ?><li><div class="timeline-marker"></div><div class="timeline-content"><div class="timeline-heading"><strong><?= htmlspecialchars($dispatch['decision'] ?: 'Despacho registado', ENT_QUOTES, 'UTF-8') ?></strong><span><?= htmlspecialchars(date('d/m/Y H:i', strtotime($dispatch['created_at'])), ENT_QUOTES, 'UTF-8') ?></span></div><p><strong>Responsável:</strong> <?= htmlspecialchars($dispatch['author_name'] ?? 'Utilizador removido', ENT_QUOTES, 'UTF-8') ?></p><p><?= nl2br(htmlspecialchars($dispatch['content'], ENT_QUOTES, 'UTF-8')) ?></p><?php if ($dispatch['observation']): ?><p><strong>Observação:</strong> <?= nl2br(htmlspecialchars($dispatch['observation'], ENT_QUOTES, 'UTF-8')) ?></p><?php endif; ?></div></li><?php endforeach; ?></ol></section><?php endif; ?></main></body></html>